cd /tmp && perl -e '
for my $i (1..255) {
  my $w = chr($i);
  my $q = $w; 
  open(my $fh, "-|");
  if (!defined $fh) { die }
  1;
}
' 2>/dev/null; echo "skip"; 
# simpler: use perl to exec directly and capture
cat > /tmp/probe.pl <<'PEOF'
use strict; use warnings;
my $bin = "/workspace/dataset/test20_executable";
for my $i (1..255) {
  my $w = chr($i);
  my $pid = open(my $fh, "-|");
  if ($pid == 0) { open(STDERR, ">", "/dev/null"); exec($bin, $w) or exit 127; }
  local $/; my $out = <$fh>; $out = "" unless defined $out; close($fh);
  my $st = $?;
  my $nl = ($out =~ tr/\n//);
  my $endsnl = (length($out) && substr($out,-1) eq "\n") ? 1 : 0;
  my $sig = $st & 127; my $code = $st >> 8;
  printf("byte 0x%02X sig=%d code=%d nl=%d endsNL=%d len=%d\n", $i, $sig, $code, $nl, $endsnl, length($out));
}
PEOF
perl /tmp/probe.pl | awk '{print} $3!="sig=0" || $5!="nl=20" || $6!="endsNL=1" {print "  ^^ ANOMALY"}' | grep -B1 ANOMALY; echo "=== summary ==="; perl /tmp/probe.pl | awk '{s[$3" "$4" "$5" "$6]++} END{for(k in s) print s[k], k}'

mkdir -p /tmp/cli_edges_ag && cat > /tmp/cli_edges_ag/probe.pl <<'PEOF'
use strict; use warnings;
my $bin = "/workspace/dataset/test20_executable";
for my $i (1..255) {
  my $w = chr($i);
  my $pid = open(my $fh, "-|");
  die "fork fail" unless defined $pid;
  if ($pid == 0) { open(STDERR, ">", "/dev/null"); exec($bin, $w); exit 127; }
  local $/; my $out = <$fh>; $out = "" unless defined $out; close($fh);
  my $st = $?;
  my $nl = ($out =~ tr/\n//);
  my $endsnl = (length($out) && substr($out,-1) eq "\n") ? 1 : 0;
  printf("byte 0x%02X sig=%d code=%d nl=%d endsNL=%d len=%d\n", $i, $st & 127, $st >> 8, $nl, $endsnl, length($out));
}
PEOF
timeout 100 perl /tmp/cli_edges_ag/probe.pl > /tmp/cli_edges_ag/bytes.txt 2>&1; echo "EXIT=$?"; wc -l < /tmp/cli_edges_ag/bytes.txt; echo "=== anomalies (not sig=0 code=0 nl=20 endsNL=1) ==="; grep -v 'sig=0 code=0 nl=20 endsNL=1' /tmp/cli_edges_ag/bytes.txt

cat > /tmp/cli_edges_ag/sweep.pl <<'PEOF'
use strict; use warnings;
my $bin = "/workspace/dataset/test20_executable";
srand(1234);
my $n = 0; my $bad = 0; my $aborts = 0; my %abortwords;
for my $t (1..600) {
  my $len = int(rand(12));
  my $w = "";
  $w .= chr(1 + int(rand(255))) for (1..$len);
  next if $w =~ /\n/;   # newline words break the 20-line count by design
  $n++;
  pipe(my $rd, my $wr); pipe(my $erd, my $ewr);
  my $pid = fork(); die unless defined $pid;
  if ($pid == 0) { close $rd; close $erd; open(STDOUT,">&",$wr); open(STDERR,">&",$ewr); exec($bin,$w); exit 127; }
  close $wr; close $ewr;
  local $/; my $out = <$rd> // ""; my $err = <$erd> // "";
  waitpid($pid,0); my $st = $?;
  my $sig = $st & 127; my $code = $st >> 8;
  my $nl = ($out =~ tr/\n//);
  my $endsnl = (length($out) && substr($out,-1) eq "\n") ? 1 : 0;
  my $expect_abort = ($w eq "" || substr($w,-1) eq ":") ? 1 : 0;
  my $got_abort = ($sig == 6) ? 1 : 0;
  $aborts++ if $got_abort;
  my @prob;
  push @prob, "abort_rule_mismatch" if $expect_abort != $got_abort;
  if ($got_abort) {
    push @prob, "stdout_not_empty(len=".length($out).")" if length($out) != 0;
    push @prob, "no_stderr" if $err !~ /out_of_range/;
  } else {
    push @prob, "nl=$nl" if $nl != 20;
    push @prob, "no_trailing_nl" if !$endsnl;
    push @prob, "code=$code" if $code != 0;
    push @prob, "stderr=".length($err) if length($err) != 0;
  }
  if (@prob) { $bad++; printf("BAD w=%s : %s\n", unpack("H*",$w), join(",",@prob)); }
}
printf("probes=%d aborts=%d bad=%d\n", $n, $aborts, $bad);
PEOF
timeout 200 perl /tmp/cli_edges_ag/sweep.pl 2>&1 | tail -20

W=$(head -c 200000 /dev/zero | tr '\0' 'q' | head -c 120000); echo "len=${#W}"; ( /workspace/dataset/test20_executable "$W" 2>/tmp/cli_edges_ag/sp2.err; echo "PROG_EXIT=$?" >&2 ) | head -c 100 >/dev/null; sleep 0.3; cat /tmp/cli_edges_ag/sp2.err
echo "=== via perl to get true exit status on SIGPIPE ==="
cat > /tmp/cli_edges_ag/sp.pl <<'PEOF'
use strict; use warnings;
my $bin="/workspace/dataset/test20_executable";
my $w = "q" x 120000;
pipe(my $rd,my $wr);
my $pid=fork(); die unless defined $pid;
if($pid==0){ close $rd; open(STDOUT,">&",$wr); exec($bin,$w); exit 127; }
close $wr;
my $buf; read($rd,$buf,100);   # read only 100 bytes
close $rd;                      # then close -> SIGPIPE for writer
waitpid($pid,0); my $st=$?;
printf("sig=%d code=%d\n", $st & 127, $st >> 8);
PEOF
timeout 60 perl /tmp/cli_edges_ag/sp.pl

