use std::io::Write;

fn main() {
    let argv: Vec<std::ffi::OsString> = std::env::args_os().collect();
    // argc < 2 -> print absolutely nothing, exit 0.
    if argv.len() < 2 {
        std::process::exit(0);
    }
    // argv[2..] are ignored entirely.
    // Raw bytes, not UTF-8 validated:
    use std::os::unix::ffi::OsStrExt;
    let word: Vec<u8> = argv[1].as_os_str().as_bytes().to_vec();

    // Compute ALL 20 results BEFORE emitting anything.
    let mut r: Vec<Vec<u8>> = Vec::with_capacity(20);
    r.push(pluralize(&word));
    r.push(singularize(&word));
    r.push(camelize(&word, true));
    r.push(camelize(&word, false));
    r.push(underscore(&word));
    r.push(classify(&word));
    r.push(tableize(&word));
    r.push(humanize(&word));
    r.push(titleize(&word));
    r.push(dasherize(&word));
    r.push(parameterize(&word));
    let mut wrapped = b"A ".to_vec();
    wrapped.extend_from_slice(&word);
    wrapped.extend_from_slice(b" Test");
    r.push(parameterize(&wrapped));
    r.push(upcase(&word));
    r.push(downcase(&word));
    r.push(capitalize(&word));
    r.push(decapitalize(&word));
    r.push(truncate(&word, 5));
    let mut qualified = b"Test::".to_vec();
    qualified.extend_from_slice(&word);
    r.push(demodulize_or_abort(&qualified)); // may abort(), see other entry
    r.push(if is_plural(&word)   { b"1".to_vec() } else { b"0".to_vec() });
    r.push(if is_singular(&word) { b"1".to_vec() } else { b"0".to_vec() });

    // Emit: 20 records, each followed by a single 0x0A, flushed per record.
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for line in &r {
        let _ = out.write_all(line);   // errors are IGNORED (see /dev/full probe)
        let _ = out.write_all(b"\n");
        let _ = out.flush();
    }
    std::process::exit(0);
}

/// Reproduce line 18 including its abort behaviour.
/// s is "Test::" + word.
fn demodulize_or_abort(s: &[u8]) -> Vec<u8> {
    // find_last_of(':')
    let p = s.iter().rposition(|&b| b == b':')
        .expect("'Test::' guarantees a colon exists");
    let start = p + 2;                      // the library's +2, not +1
    if start > s.len() {
        // Faithful reproduction of the uncaught std::out_of_range:
        eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
        eprintln!("  what():  basic_string::substr: __pos (which is {}) > this->size() (which is {})",
                  start, s.len());
        std::process::abort();              // raises SIGABRT -> shell sees 134
    }
    s[start..].to_vec()
}

/// Equivalent cheap predicate, if you only need to know *whether* it aborts:
fn will_abort(word: &[u8]) -> bool {
    word.is_empty() || *word.last().unwrap() == b':'
}

// Emit exactly the framing the C++ binary uses.
fn emit(results: &[Vec<u8>; 20]) {
    use std::io::Write;
    let so = std::io::stdout();
    let mut w = so.lock();
    for r in results {
        let _ = w.write_all(r);
        let _ = w.write_all(b"\n");   // ALWAYS, including after the 20th
        let _ = w.flush();            // one write(2) per record, see buffering entry
    }
    // nothing else: no extra newline, no stderr output
}

// Differential-comparison helper: never split on b'\n'; compare whole stdout.
fn same_stdout(a: &[u8], b: &[u8]) -> bool { a == b }

use std::io::Write;

fn emit_like_cpp(records: &[Vec<u8>]) {
    // Match the C++ binary's default SIGPIPE disposition (Rust ignores it):
    #[cfg(unix)]
    unsafe { libc::signal(libc::SIGPIPE, libc::SIG_DFL); }

    let so = std::io::stdout();
    let mut w = so.lock();
    for r in records {
        let _ = w.write_all(r);
        let _ = w.write_all(b"\n");
        let _ = w.flush();   // one write(2) syscall per record, even to a file
        // NOTE: all three results are deliberately discarded — the C++ program
        // ignores write errors entirely and still exits 0 (see /dev/full probe).
    }
}
